  private import ScalarValues::*;
  part def Controller {
    in attribute io_1 : Integer;
    attribute phaseMs : Integer := 0;
    attribute ledOn : Boolean := false;
    perform action tick {
      first start;
      then assign phaseMs := phaseMs + io_1;
      then if ledOn {
        first start;
        then if phaseMs >= 1000 {
          first start;
          then assign phaseMs := phaseMs - 1000;
          then assign ledOn := false;
        }
      }
      then if (not ledOn) {
        first start;
        then if phaseMs >= 2000 {
          first start;
          then assign phaseMs := phaseMs - 2000;
          then assign ledOn := true;
        }
        then if ((ledOn) and ((not phaseMs >= 2000))) {
          first start;
          then done;
        }
      }
      then if ((ledOn) and (phaseMs >= 3000)) {
        first start;
        then assign phaseMs := phaseMs - 3000;
        then assign ledOn := false;
      }
      then if (((not ledOn)) and (phaseMs >= 3000)) {
        first start;
        then assign phaseMs := phaseMs - 3000;
        then assign ledOn := true;
      }
    }
    out attribute io_0 : Boolean = ledOn;
  }
  part system : Controller;
}

